"""The embed catalog, generated by Go (`pnpm gen:openapi`, server/internal/embeds).

Every element type a material document may hold and the rich embed kinds with
their name in each layer (openwiki/embeds.md). The pipeline reads the kind
lists it needs from here instead of repeating them; the media schemas the
agent's question media are checked against reach it through the agent
contract (``contract.MEDIA_BLOCKS``), which Go builds from the same catalog.
"""

from __future__ import annotations

import json
from importlib import resources
from typing import Any

CATALOG: dict[str, Any] = json.loads(
    resources.files("pipeline.generated").joinpath("embeds.json").read_text("utf-8")
)
EMBEDS: dict[str, dict[str, Any]] = {e["kind"]: e for e in CATALOG["embeds"]}
# Kinds that are question blocks too: chart, plot and graph.
QUESTION_BLOCK_KINDS: frozenset[str] = frozenset(
    kind for kind, embed in EMBEDS.items() if embed.get("questionBlock")
)
